  font-size: 13px;
  line-height: 1.7;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

/* Typing Animation */

.typing-indicator {
  display: flex;
  align-items: center;
  gap: 5px;
  padding: 4px 1px;
}

.typing-indicator span {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: #8a98b1;
  border: none;
  animation: typing 1.2s infinite ease-in-out;
}

.typing-indicator span:nth-child(2) {
  animation-delay: 0.15s;
}

.typing-indicator span:nth-child(3) {
  animation-delay: 0.3s;
}

@keyframes typing {
  0%,
  60%,
  100% {
    opacity: 0.4;
    transform: translateY(0);
  }

  30% {
    opacity: 1;
    transform: translateY(-4px);
  }
}

/* Error Message */

.error-message {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  padding: 10px 12px;
  color: #a52b35;
  background: #fff1f1;
  border: none;
  border-radius: 9px;
  box-shadow: none;
  font-size: 12px;
  line-height: 1.6;
  overflow-wrap: anywhere;
}

.error-message button {
  flex-shrink: 0;
  padding: 0;
  color: inherit;
  background: transparent;
  border: none;
  box-shadow: none;
  cursor: pointer;
  font-size: 20px;
  line-height: 1;
}

/* Input Area */

.chat-footer {
  flex-shrink: 0;
  padding: 13px 15px 10px;
  background: #ffffff;
  border: none;
  box-shadow: none;
}

/* Restored Message Input Box */

.input-container {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  padding: 8px 8px 8px 13px;
  background: #f8fafc;
  border: 1px solid #dfe5ef;
  border-radius: 12px;
  box-shadow: none;
  transition: border-color 0.2s, background 0.2s;
}

.input-container:focus-within {
  background: #ffffff;
  border-color: #8ca7ff;
  box-shadow: none;
}

.input-container textarea {
  flex: 1;
  min-width: 0;
  min-height: 25px;
  max-height: 100px;
  padding: 4px 0;
  resize: vertical;
  color: #26334a;
  background: transparent;
  border: none;
  outline: none;
  box-shadow: none;
  font-size: 13px;
  line-height: 1.6;
}

.input-container textarea::placeholder {
  color: #9aa4b5;
}

.input-container textarea:disabled {
  opacity: 0.6;
  cursor: not-allowed;
}

.send-button {
  width: 35px;
  height: 35px;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #ffffff;
  background: #315de7;
  border: none;
  border-radius: 9px;
  box-shadow: none;
  cursor: pointer;
  transition: background 0.2s, transform 0.2s;
}

.send-button svg {
  width: 19px;
  height: 19px;
  fill: none;
  stroke: currentColor;
  stroke-width: 2;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.send-button:hover:not(:disabled) {
  background: #244bc9;
}

.send-button:active:not(:disabled) {
  transform: scale(0.95);
}

.send-button:disabled {
  background: #a9b9ed;
  box-shadow: none;
  cursor: not-allowed;
}

/* Footer Note */

.footer-note {
  margin: 9px 0 0;
  color: #9aa4b5;
  font-size: 10px;
  line-height: 1.5;
  text-align: center;
}

/* Smaller Appsmith Widget Dimensions */

@media (max-width: 480px) {
  .chat-header {
    padding: 12px;
  }

  .chat-messages {
    padding: 14px 10px;
    gap: 14px;
  }

  .message-bubble {
    max-width: 88%;
    padding: 10px 11px;
  }

  .chat-footer {
    padding: 10px;
  }

  .header-info h2 {
    font-size: 14px;
  }
}

