import React, { useState, useRef, useEffect } from "https://esm.sh/react@18.2.0";
import ReactDOM from "https://esm.sh/react-dom@18.2.0";

const API_KEY = "AQ.Ab8RN6IQPgD_ISp4cwI24gnO8C29_NghER0KFlbggjQp3p8lQw";
const MODEL = "gemini-3.8-flash";

const API_URL =
  `https://generativelanguage.googleapis.com/v1beta/models/${MODEL}:generateContent`;

function Chatbot() {
  const [messages, setMessages] = useState([
    {
      role: "assistant",
      content: "Hi! I'm your AI assistant. How can I help you today?"
    }
  ]);

  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  const bottomRef = useRef(null);
  const inputRef = useRef(null);

  useEffect(() => {
    bottomRef.current?.scrollIntoView({ behavior: "smooth" });
  }, [messages, loading, error]);

  async function sendMessage() {
    const text = input.trim();

    if (!text || loading) return;

    if (
      !API_KEY ||
      API_KEY === "PASTE_YOUR_GEMINI_API_KEY_HERE"
    ) {
      setError("Please add your Gemini API key in the React code.");
      return;
    }

    const previousMessages = messages;
    const updatedMessages = [
      ...previousMessages,
      { role: "user", content: text }
    ];

    setMessages(updatedMessages);
    setInput("");
    setError("");
    setLoading(true);

    try {
      const contents = updatedMessages.map((message) => ({
        role: message.role === "assistant" ? "model" : "user",
        parts: [{ text: message.content }]
      }));

      const response = await fetch(API_URL, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-goog-api-key": API_KEY
        },
        body: JSON.stringify({
          systemInstruction: {
            parts: [
              {
                text:
                  "You are a helpful AI assistant. Give clear, " +
                  "friendly and accurate answers. Admit when you " +
                  "do not know something."
              }
            ]
          },
          contents,
          generationConfig: {
            temperature: 0.7,
            maxOutputTokens: 1024
          }
        })
      });

      const data = await response.json().catch(() => null);

      if (!response.ok) {
        const apiError =
          data?.error?.message ||
          `Gemini API request failed with HTTP ${response.status}.`;

        throw new Error(apiError);
      }

      const answer = (data?.candidates?.[0]?.content?.parts || [])
        .map((part) => part.text || "")
        .join("")
        .trim();

      if (!answer) {
        const reason = data?.candidates?.[0]?.finishReason;

        throw new Error(
          reason
            ? `Gemini returned no text. Finish reason: ${reason}.`
            : "Gemini returned an empty response. Please try again."
        );
      }

      setMessages((current) => [
        ...current,
        { role: "assistant", content: answer }
      ]);
    } catch (err) {
      console.error("Gemini chatbot error:", err);

      let message = err.message || "An unexpected error occurred.";

      if (err instanceof TypeError) {
        message =
          "Network request failed. Check your internet connection " +
          "and whether Appsmith allows the Gemini API request. " +
          "If the browser reports a CORS error, a backend proxy may be required.";
      }

      setError(message);
    } finally {
      setLoading(false);
      inputRef.current?.focus();
    }
  }

  function handleKeyDown(event) {
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      sendMessage();
    }
  }

  function clearChat() {
    if (loading) return;

    setMessages([
      {
        role: "assistant",
        content: "Chat cleared! What would you like to discuss?"
      }
    ]);

    setInput("");
    setError("");
  }

  return (
    <div className="chatbot">
      <header className="chat-header">
  <div className="header-left">
    <div className="bot-avatar">
      <svg viewBox="0 0 24 24" aria-hidden="true">
        <path d="M12 3v2M8 5h8a4 4 0 0 1 4 4v6a4 4 0 0 1-4 4H8a4 4 0 0 1-4-4V9a4 4 0 0 1 4-4Z" />
        <circle cx="9" cy="11" r="1" />
        <circle cx="15" cy="11" r="1" />
        <path d="M9 15h6" />
      </svg>
    </div>

    <div className="header-info">
      <h2>AI Assistant</h2>
      <span className="online-status">
        <span className="online-dot" />
        Powered by Google Gemini
      </span>
    </div>
  </div>

  <div className="header-actions">
    <button
      className="clear-button"
      onClick={clearChat}
      disabled={loading}
      title="Clear conversation"
      aria-label="Clear conversation"
    >
      <svg viewBox="0 0 24 24" aria-hidden="true">
        <path d="M3 6h18M9 6V4h6v2m-9 0 1 14h10l1-14M10 10v6m4-6v6" />
      </svg>
    </button>

    <button
      className="close-x-btn"
      onClick={() =>
        window.appsmith?.triggerEvent?.("onResetClick")
      }
      title="Close chat"
      aria-label="Close chat"
    >
      &times;
    </button>
  </div>
</header>

      <main className="chat-messages">
        {messages.map((message, index) => (
          <div
            key={index}
            className={`message-row ${
              message.role === "user" ? "user-row" : "assistant-row"
            }`}
          >
            {message.role === "assistant" && (
              <div className="message-avatar">AI</div>
            )}

            <div
              className={`message-bubble ${
                message.role === "user"
                  ? "user-bubble"
                  : "assistant-bubble"
              }`}
            >
              <div className="message-text">{message.content}</div>
            </div>
          </div>
        ))}

        {loading && (
          <div className="message-row assistant-row">
            <div className="message-avatar">AI</div>
            <div className="message-bubble assistant-bubble">
              <div className="typing-indicator">
                <span />
                <span />
                <span />
              </div>
            </div>
          </div>
        )}

        {error && (
          <div className="error-message" role="alert">
            <span>{error}</span>
            <button
              onClick={() => setError("")}
              aria-label="Dismiss error"
            >
              ×
            </button>
          </div>
        )}

        <div ref={bottomRef} />
      </main>

      <footer className="chat-footer">
        <div className="input-container">
          <textarea
            ref={inputRef}
            value={input}
            onChange={(event) => setInput(event.target.value)}
            onKeyDown={handleKeyDown}
            placeholder="Message your AI assistant..."
            rows={1}
            disabled={loading}
            aria-label="Message"
          />

          <button
            className="send-button"
            onClick={sendMessage}
            disabled={!input.trim() || loading}
            aria-label="Send message"
            title="Send message"
          >
            <svg viewBox="0 0 24 24" aria-hidden="true">
              <path d="M12 19V5M5 12l7-7 7 7" />
            </svg>
          </button>
        </div>

        <p className="footer-note">
          AI can make mistakes. Verify important information.
        </p>
      </footer>
    </div>
  );
}

const rootElement = document.getElementById("root");

if (rootElement) {
  ReactDOM.createRoot(rootElement).render(<Chatbot />);
}
